export const BASE_ITEM_MAX_PLACED = 26; // plafond maison conservé (ROSA); RSE = 16

const BASE_ITEMS_BY_SLUG = (() => { const m = {}; for (const it of BASE_ITEMS) m[it.s] = it; return Object.freeze(m); })();

export function baseItemGet(slug) { return BASE_ITEMS_BY_SLUG[slug] || null; }
export function baseItemNameKey(slug) { return 'base.i.' + slug; }
export function baseItemList(cat) { return cat ? BASE_ITEMS.filter((i) => i.cat === cat) : BASE_ITEMS.slice(); }

// Passe 42: rotation REMOVED (RSE canon + user request) — counters
// frozen to 1, normalization -> 0. Signatures stay (callers unchanged).
export function baseItemRotCount(item) { return 1; }
export function baseItemRotNormalize(item, rotIndex) { return 0; }

// COLLISION/placement footprint:
//  - surface (dolls/cushions): 1×1 on the base tile;
//  - behind (plants/shields, 1×2 or 2×2 shape): base row w×1;
//  - over (phase 45, slide): the `over` HIGH rows are a purely visual
//    overhang -> the footprint only keeps the low rows;
//  - otherwise: full canon shape (desks 3×2, mats 3×3, stand 4×2…).
export function baseItemFootprint(item, rotIndex) {
  if (!item) return { w: 1, d: 1 };
  if (item.layer === 'surface') return { w: 1, d: 1 };
  if (item.behind) return { w: item.w, d: 1 };
  if (item.over) return { w: item.w, d: Math.max(1, (item.d || 1) - item.over) };
  return { w: item.w, d: item.d };
}

// Offset (in tiles) between the DRAWING ORIGIN and the footprint origin.
// An "over" object is stored at its FOOTPRINT origin (low rows); its full
// sprite therefore starts `over` tiles HIGHER. Renderers and the editor
// use this offset to draw the overhang in the right place.
export function baseItemDrawOffset(item) {
  return (item && item.over) ? { dx: 0, dy: -item.over } : { dx: 0, dy: 0 };
}

